(7255681, 1128210, 24983, '<td valign="top">the balloons should be more prominent but it is a nice portrait</td>', 'the balloons should be more prominent but it is a nice portrait', '2014-08-27 01:15:03.000000', NULL, 1),
(7255694, 1127833, 50641, '<td valign="top">Need longer slip</td>', 'Need longer slip', '2014-08-27 01:32:30.000000', NULL, 1),
(7255725, 1128194, 6519, '<td valign="top">Ouch !!!! Why ????<br/>Two points for meeting the challenge topic.... but you lose several points for the pain you caused me. If you''re trying for the brown ribbon, I bet it would need to be even worse than this..... try a very underexposed b&amp;w and add a layer of gaussian blur.</td>', 'Ouch !!!! Why ????Two points for meeting the challenge topic.... but you lose several points for the pain you caused me. If you''re trying for the brown ribbon, I bet it would need to be even worse than this..... try a very underexposed b&w and add a layer of gaussian blur.', '2014-08-27 03:22:43.000000', NULL, 1),
(7255726, 1128319, 6519, '<td valign="top">You should offer this on DP prints.... I bet you could retire on your earnings from this "image" ;-)</td>', 'You should offer this on DP prints.... I bet you could retire on your earnings from this "image" ;-)', '2014-08-27 03:23:49.000000', NULL, 1),
(7255727, 1128314, 6519, '<td valign="top">What a fabulous interesting, moment - captured in colourful sharpness. Love it! You even managed a rather elegant composition.</td>', 'What a fabulous interesting, moment - captured in colourful sharpness. Love it! You even managed a rather elegant composition.', '2014-08-27 03:25:23.000000', NULL, 1),
(7255728, 1128297, 6519, '<td valign="top">A lovely, tender moment.... nice composition, pretty colours, even a touch of detail left in the murky shadows ahead. Very nice.</td>', 'A lovely, tender moment.... nice composition, pretty colours, even a touch of detail left in the murky shadows ahead. Very nice.', '2014-08-27 03:26:22.000000', NULL, 1),
(7255729, 1128226, 6519, '<td valign="top">Bizarre, weird, thought provoking, entertaining..... I like it!!!!! The vignette is very nice touch, too.</td>', 'Bizarre, weird, thought provoking, entertaining..... I like it!!!!! The vignette is very nice touch, too.', '2014-08-27 03:27:14.000000', NULL, 1),
