(7255937, 1128243, 149964, '<td valign="top">Sad picture! I''d have given it a higher mark if the sky wasn''t so distracting - a bit too bright for me!</td>', 'Sad picture! I''d have given it a higher mark if the sky wasn''t so distracting - a bit too bright for me!', '2014-08-27 17:12:06.000000', NULL, 1),
(7255938, 1127863, 149964, '<td valign="top">It took me a while for me to get to the heart of this picture - I''m afraid I found it a bit too dark,.</td>', 'It took me a while for me to get to the heart of this picture - I''m afraid I found it a bit too dark,.', '2014-08-27 17:13:03.000000', NULL, 1),
(7255939, 1128250, 149964, '<td valign="top">I really like the contrast of the colours, and the simplicity,  but there was something (too soft?) about the middle of the darker balloon that bothered me.</td>', 'I really like the contrast of the colours, and the simplicity,  but there was something (too soft?) about the middle of the darker balloon that bothered me.', '2014-08-27 17:14:48.000000', NULL, 1),
(7255940, 1128242, 149964, '<td valign="top">This made me smile! However, I think the balloons are rather lost in the background rather than being the focus of the picture.</td>', 'This made me smile! However, I think the balloons are rather lost in the background rather than being the focus of the picture.', '2014-08-27 17:16:32.000000', NULL, 1),
(7255941, 1128209, 149964, '<td valign="top">I love the right hand side: colours and lighting are lovely. I''m not so sure about the left - personally I''d have preferred less dark shadows.</td>', 'I love the right hand side: colours and lighting are lovely. I''m not so sure about the left - personally I''d have preferred less dark shadows.', '2014-08-27 17:18:08.000000', NULL, 1),
(7255942, 1128210, 149964, '<td valign="top">What a cutey! GIven the challenge, though,  I''d have preferred to have seen more of the balloons.</td>', 'What a cutey! GIven the challenge, though,  I''d have preferred to have seen more of the balloons.', '2014-08-27 17:19:40.000000', NULL, 1),
(7255943, 1128204, 149964, '<td valign="top">Great idea: simple subject and something different. I''m afraid I wasn''t so keen on the pale blue/grey combination, something not quite striking enough for me.</td>', 'Great idea: simple subject and something different. I''m afraid I wasn''t so keen on the pale blue/grey combination, something not quite striking enough for me.', '2014-08-27 17:21:46.000000', NULL, 1),
(7255944, 1127928, 149964, '<td valign="top">What a great expression on the little one''s face! I found the background was a bit cluttered for my liking and thought this detracted from the subject.</td>', 'What a great expression on the little one''s face! I found the background was a bit cluttered for my liking and thought this detracted from the subject.', '2014-08-27 17:22:54.000000', NULL, 1),
(7255945, 1128307, 149964, '<td valign="top">Clever idea and some lovely colours. Personally I''d have liked it a little simpler; a bit too much going on for me.</td>', 'Clever idea and some lovely colours. Personally I''d have liked it a little simpler; a bit too much going on for me.', '2014-08-27 17:24:39.000000', NULL, 1),
(7255946, 1128317, 149964, '<td valign="top">Clever idea and I like the curve of the parrot which drew my eyes in to the flowers.</td>', 'Clever idea and I like the curve of the parrot which drew my eyes in to the flowers.', '2014-08-27 17:28:06.000000', NULL, 1),
