(7257595, 1127833, 37858, '<td valign="top">Nice emotional tug to the image.  Should be a top ten finish IMHO.</td>', 'Nice emotional tug to the image.  Should be a top ten finish IMHO.', '2014-09-01 23:35:17.000000', NULL, 1),
(7257596, 1128314, 37858, '<td valign="top">I like the colors and the energy.</td>', 'I like the colors and the energy.', '2014-09-01 23:35:34.000000', NULL, 1),
(7257597, 1127861, 37858, '<td valign="top">I have a love/hate reaction to this image.  On the one hand, I love the perspective, subject matter and the layers of terrain.  On the other hand, I wish this was not so desaturated or (perhaps) split toned.  Still, love triumphs over hate, so I scored it well.</td>', 'I have a love/hate reaction to this image.  On the one hand, I love the perspective, subject matter and the layers of terrain.  On the other hand, I wish this was not so desaturated or (perhaps) split toned.  Still, love triumphs over hate, so I scored it well.', '2014-09-01 23:37:37.000000', NULL, 1),
(7257599, 1128226, 98339, '<td valign="top">You could have titled this "Gently, Gently"....lol</td>', 'You could have titled this "Gently, Gently"....lol', '2014-09-01 23:44:58.000000', NULL, 1),
(7257615, 1128297, 120129, '<td valign="top">This shot lovely, so reminds me of my grandson.  I can''t help but wonder what this would have looked like if he were much further down the road. Interesting!</td>', 'This shot lovely, so reminds me of my grandson.  I can''t help but wonder what this would have looked like if he were much further down the road. Interesting!', '2014-09-02 00:50:59.000000', NULL, 1),
